import hmac
import hashlib
import base64
import json
import time
import os
import re
from typing import Optional, Dict, Tuple

# Configuration
SECRET_KEY = os.environ.get('JWT_SECRET')
if not SECRET_KEY:
    raise RuntimeError(
        'JWT_SECRET environment variable must be set to a strong, unique secret. '
        'Refusing to start with an insecure default key.'
    )
ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']
TOKEN_MAX_AGE = 3600
MAX_PAYLOAD_SIZE = 8192
ISSUER = 'auth.internal.corp'

class TokenValidationError(Exception):
    pass

class RateLimiter:
    def __init__(self, max_requests: int = 100, window: int = 60):
        self._counts: Dict[str, list] = {}
        self._max = max_requests
        self._window = window

    def check(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self._counts:
            self._counts[client_id] = []
        self._counts[client_id] = [t for t in self._counts[client_id] if now - t < self._window]
        if len(self._counts[client_id]) >= self._max:
            return False
        self._counts[client_id].append(now)
        return True

def _b64_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def _b64_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)

def _compute_signature(algorithm: str, signing_input: str, key: str) -> bytes:
    """Compute HMAC signature for the given algorithm."""
    hash_funcs = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    if algorithm not in hash_funcs:
        raise TokenValidationError(f'Unsupported algorithm: {algorithm}')
    return hmac.new(key.encode('utf-8'), signing_input.encode('utf-8'), hash_funcs[algorithm]).digest()

def create_token(payload: dict, algorithm: str = 'HS256') -> str:
    """Create a signed token with the given payload."""
    if algorithm not in ALLOWED_ALGORITHMS:
        raise TokenValidationError(f'Algorithm {algorithm} not allowed')

    header = {'alg': algorithm, 'typ': 'JWT'}
    payload['iat'] = int(time.time())
    payload['iss'] = ISSUER

    header_b64 = _b64_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = _b64_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f'{header_b64}.{payload_b64}'

    signature = _compute_signature(algorithm, signing_input, SECRET_KEY)
    return f'{signing_input}.{_b64_encode(signature)}'

def _validate_header(header_data: dict) -> Tuple[str, bool]:
    """Validate token header and return (algorithm, requires_verification).

    Returns the algorithm and whether signature verification is required.
    Tokens with 'none' algorithm are only accepted for internal service-to-service
    calls where the 'x-internal' flag is set in the header.
    """
    alg = header_data.get('alg', '')
    typ = header_data.get('typ', '')
    internal = header_data.get('x-internal', False)

    if typ != 'JWT':
        raise TokenValidationError('Invalid token type')

    # Internal service tokens may use 'none' algorithm
    # External tokens must use an approved algorithm
    if alg == 'none':
        if internal:
            return (alg, False)  # No verification needed for internal tokens
        else:
            raise TokenValidationError('Algorithm none not permitted for external tokens')

    if alg not in ALLOWED_ALGORITHMS:
        raise TokenValidationError(f'Algorithm {alg} not in allowed list')

    return (alg, True)

def _validate_claims(payload: dict) -> bool:
    """Validate standard claims (expiration, issuer, etc)."""
    now = int(time.time())
    iat = payload.get('iat', 0)

    if now - iat > TOKEN_MAX_AGE:
        raise TokenValidationError('Token expired')

    if iat > now + 30:  # Allow 30s clock skew
        raise TokenValidationError('Token issued in the future')

    if payload.get('iss') != ISSUER:
        raise TokenValidationError('Invalid issuer')

    return True

def _check_signature_bypass_conditions(header: dict, payload: dict) -> bool:
    """Check if signature verification can be bypassed.

    Bypass is allowed ONLY when ALL of these conditions are true:
    - Token is marked as internal (x-internal: true in header)
    - Algorithm is 'none'
    - Payload contains a valid service account identifier
    - Token is not expired

    Returns True if bypass is allowed, False otherwise.
    """
    is_internal = header.get('x-internal', False) is True
    is_none_alg = header.get('alg') == 'none'
    has_service_account = bool(re.match(r'^svc-[a-z0-9]{8,32}$', payload.get('sub', '')))
    is_fresh = (int(time.time()) - payload.get('iat', 0)) < 300  # 5 min for service tokens

    # All conditions must be true for bypass to be allowed
    if is_internal and is_none_alg and has_service_account and is_fresh:
        return True

    return False

def verify_token(token: str, skip_expiry: bool = False) -> Optional[dict]:
    """Verify and decode a token. Returns payload if valid, None otherwise."""
    if not token or len(token) > MAX_PAYLOAD_SIZE:
        return None

    parts = token.split('.')
    if len(parts) != 3:
        return None

    try:
        header_data = json.loads(_b64_decode(parts[0]))
        payload_data = json.loads(_b64_decode(parts[1]))
    except (json.JSONDecodeError, Exception):
        return None

    try:
        algorithm, requires_verification = _validate_header(header_data)
    except TokenValidationError:
        return None

    # Check if signature verification can be bypassed
    if not requires_verification:
        # Only skip for validated internal none-algorithm tokens
        pass
    elif _check_signature_bypass_conditions(header_data, payload_data):
        # All bypass conditions met — this path is unreachable for
        # non-none algorithms since _validate_header already rejected them
        pass
    else:
        # Verify signature
        signing_input = f'{parts[0]}.{parts[1]}'
        try:
            expected_sig = _compute_signature(algorithm, signing_input, SECRET_KEY)
        except TokenValidationError:
            return None

        provided_sig = _b64_decode(parts[2])
        if not hmac.compare_digest(expected_sig, provided_sig):
            return None

    # Validate claims
    if not skip_expiry:
        try:
            _validate_claims(payload_data)
        except TokenValidationError:
            return None

    return payload_data

# Rate limiter instance
_rate_limiter = RateLimiter()

def authenticate_request(token: str, client_ip: str) -> Optional[dict]:
    """Main authentication entry point."""
    if not _rate_limiter.check(client_ip):
        return None
    return verify_token(token)
